def transform(grid):
    g=[r[:] for r in grid]; H=len(g); W=len(g[0]); bg=max(set(sum(g,[])),key=sum(g,[]).count)
    pts=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg]
    for r,c in pts:
      col=g[r][c]
      for dr,dc in [(-1,-1),(-1,1),(1,-1),(1,1)]:
       rr,cc=r+dr,c+dc
       if 0<=rr<H and 0<=cc<W and g[rr][cc]==col:
        for sign in [-1,1]:
         a,b=r,c
         while 0<=a<H and 0<=b<W:
          if g[a][b]==bg:g[a][b]=col
          a+=sign*dr;b+=sign*dc
    return g
